        private static readonly System.Collections.Generic.Dictionary<(short, short), string> Chunks = new System.Collections.Generic.Dictionary<(short, short), string> {
            { ((short)51, (short)0), "AN OFFICIAL LOOKING NOTICE\r\rYARASH,\r\r\"THE TIME HAS COME FOR YOU\rTO ADD YOUR POWER TO THE\rGROWING LEGIONS OF MY\rFOLLOWERS.\r" },
            { ((short)51, (short)1), "COME AND SUPPLICANT\rYOURSELF TO ME AND I WILL\rREWARD YOU AS AN IMPORTANT\rOFFICER IN MY MAGICAL\rFORCES. YOU WILL SERVE AS\rTHE ADVISOR TO THE COHORT\rOF SOLDIERS TO BE BASED AT\rSORCERER'S ISLAND. RESIST\rAND YOU SHALL BE CRUSHED" },
            { ((short)51, (short)2), "BEFORE MY ALMIGHTY POWER. I\rEXPECT YOUR POSITIVE REPLY\rWITHIN THE WEEK.\"\r\rSIGNED,\rTHE BOSS" },
            { ((short)52, (short)0), "TOLD IN A TRIUMPHANT TONE.\r\r\"YOU HAVE NO UNDERSTANDING\rOF THE SUBTLETY OF\rTYRANTHRAXUS AND HIS\rALLIES. HERE YOU HAVE\rTRUSTED ME ENOUGH TO LET\rYOUR GUARD DOWN. NOW YOU\rARE MY PRISONERS." },
            { ((short)52, (short)1), "\r\"MY KOBOLD FRIENDS DESERVE\rSOME REWARD FOR THEIR HELP.\rTHEREFORE, YOU ARE TO BE\rTAKEN TO THEIR PIT. THERE,\rUNARMED, YOU SHALL FIGHT\rBERSHEERA, MY PET SERPENT.\rHE SHOULD BE HUNGRY NOW,\rMERCHANTS DON'T SATISFY HIM" },
            { ((short)52, (short)2), "FOR LONG.\"" },
            { ((short)53, (short)0), "TOLD IN HALTING SPEECH.\r\r\"THANK YOU FOR FREEING US.\rYARASH HAS BEEN\rEXPERIMENTING ON OUR\rPEOPLE, CHANGING THEM IN\rHORRIBLE WAYS. EVERY NIGHT\rWE CARRY OFF ANOTHER LIZARD\rMAN WITH HIS CHEST BURST" },
            { ((short)53, (short)1), "OPEN OR HIS HEAD MANGLED.\rYARASH SAY HE MAKE US LIKE\rSA-HAG-AN. HE ALWAYS SAY\rTHAT HE MAKE US STRONGER,\rBETTER HUNTERS. BUT ALL HE\rMAKE US IS DEAD.\r\r\"WE WERE NOT ALLOWED TO\rSPEAK WHEN YARASH WAS" },
            { ((short)53, (short)2), "AROUND. THESE MARKS WERE\rPASSED DOWN TO US AND\rREMIND US OF HOME. THEY\rREPRESENT THE FRIEND WORD\rUSED BETWEEN LIZARD MEN OF\rDIFFERENT TRIBES. IF YOU\rMEET LIZARD MEN ON THE\rOUTSIDE, THIS WORD MAY HELP\rYOU.\"" },
            { ((short)53, (short)3), "\rTHE LIZARD MAN CAREFULLY\rSCRATCHES MARKS INTO THE\rDIRT. YOU RECOGNIZE THE\rMARKS AS TWO RUNES AND A\rPATH SYMBOL.\r\r(PICTURE: LIZARD MAN'S\rMARKINGS)" },
            { ((short)54, (short)0), "CAREFULLY PREPARED NOTES.\r\rNOTE 4: \"HE HAS FOOLED ME.\rALL THIS TIME HE HAS CALLED\rHIMSELF TYRANTHRAXUS THE\rFLAMED ONE. HE EXHIBITED\rHIS FLAME, AND SPOKE OF\rDEEDS ATTRIBUTED TO\rTYRANTHRAXUS. BUT TODAY," },
            { ((short)54, (short)1), "WHILE HE DID NOT KNOW I WAS\rAROUND, HE REVEALED HIS\rTRUE IDENTITY. HE SPOKE\rINTO THE GREAT POOL IN HIS\rLAIR. I THINK HE SPOKE TO\rLORD BANE HIMSELF. AND HE\rREFERRED TO HIMSELF AS\rMARAM. MARAM, HE OF THE\rGREAT SPEAR, IS ALSO A" },
            { ((short)54, (short)2), "SERVANT OF BANE.\r\r\"WHY WOULD MY LEADER USE A\rFALSE NAME? HE HIDES HIS\rTRUE IDENTITY FROM THE\rWORLD, SO THAT THEY DO NOT\rRESEARCH HIS PAST AND\rDISCOVER HIS WEAKNESSES.\rWHAT IF HE ALSO HIDES HIS" },
            { ((short)54, (short)3), "IDENTITY FROM HIS CLOSEST\rADVISORS, SO THAT THEY ALSO\rCANNOT KNOW HIS TRUE\rABILITIES AND WEAKNESSES.\rANYONE WHO ATTACKED HIM,\rTHINKING TO UTILIZE THE\rWEAKNESSES OF TYRANTHRAXUS,\rWOULD BE DESTROYED BY THE\rDIFFERENT POWERS OF MARAM" },
            { ((short)54, (short)4), "OF THE GREAT SPEAR.\r\r\"MY RESEARCH INTO\rTYRANTHRAXUS IS NOW\rUSELESS. I MUST SCOUR MY\rRECORDS FOR DETAILS\rCONCERNING MARAM OF THE\rGREAT SPEAR. I HAVE MUCH\rWORK TO DO.\"" },
            { ((short)55, (short)0), "A MASSIVE ATLAS DRAWN BY\rTHE GREAT MATHEMATICIAN\rTOMARUS.\r\r(PICTURE 1)\r\r(PICTURE 2)\r\r(PICTURE 3)" },
            { ((short)56, (short)0), "SEVERAL PIECES OF PAPER\rWITH HIGHLY ORGANIZED\rWRITING.\r\rFACT: WERNER VON URSLINGEN\rIS A RETIRED MERCENARY\rCAPTAIN TURNED BUSINESS\rMAN.\r" },
            { ((short)56, (short)1), "STRONG RUMOR: MOSTLY\rINTERESTED IN THE MILITARY\rASPECTS OF THE RECONQUEST\rOF PHLAN.\r\rRUMOR: FOUGHT IN A\rMERCENARY UNIT HIRED BY THE\rBOSS EARLY IN HIS CAREER.\r" },
            { ((short)56, (short)2), "RUMOR: HATES ZHENTARIM\rBECAUSE HE FOUGHT IN A UNIT\rAGAINST THEM SEVERAL TIMES.\r\rRUMOR: HAS STRONG CONTACTS\rWITH OTHER MERCENARIES AND\rSOME RUFFIANS IN TOWN; NONE\rOF OUR INFORMANTS CONFIRM\rSUCH CONTACT." },
            { ((short)56, (short)3), "\rVAGUE RUMOR: VON\rURSLINGEN'S UNIT WAS WIPED\rOUT BY ENEMY MAGIC USERS;\rHE WAS THE ONLY SURVIVOR;\rHE RETIRED AND NOW SECRETLY\rHATES MAGIC USERS." },
            { ((short)57, (short)0), "A PRESERVED PARCHMENT\rCOVERED WITH GIANT SCRIPT.\r\r\"I AM WRITING TO YOU TO\rDESCRIBE MY FURTHER\rINQUIRIES INTO THE LEGEND\rOF THE POOL OF RADIANCE. IT\rSEEMS THE POOL HAS MOVED\rSEVERAL TIMES. LONG AGO, AT" },
            { ((short)57, (short)1), "LEAST ONE WISE WIZARD\rACTUALLY MOVED THE POOL\rINTO HIS ABODE FOR A PERIOD\rOF TIME TO STUDY IT.\rHOWEVER, THE POOL SEEMS TO\rRETURN TO ITS ORIGINAL\rLOCATION AFTER EVERY MOVE.\rI AM NOW WATCHING THE DRY\rHOLE THAT IS THE POOL'S" },
            { ((short)57, (short)2), "NATURAL LOCATION. WHEN IT\rRETURNS I WILL BE READY. I\rTRULY BELIEVE THAT THE POOL\rOF RADIANCE IS THE KEY TO\rTHE SECRET WISDOM THAT I\rSEEK.\"\r\rYOURS IN WISDOM\rSORRASSAR" },
            { ((short)58, (short)0), "A QUICK NOTE ON AN OFTEN\rUSED PIECE OF PAPER.\r\r\"BOTH KOBOLDS AND\rHOBGOBLINS EXIST IN LARGE\rNUMBERS TO THE EAST.\rEXPERIMENTS SHOW NEITHER\rMAKES GOOD BREEDING\rMATERIAL.\"" },
            { ((short)59, (short)0), "A CLEAN MAP DRAWN WITH\rEXACT LINES.\r\r(PICTURE)" },
            { ((short)60, (short)0), "A SKETCH DRAWING.\r\r(PICTURE)" },
            { ((short)61, (short)0), "A LOOSELY WRAPPED SCROLL.\r\r\"ARAMALG-THE-GOOD, PALADIN\rAND BROTHER OF\rTAIMALG-THE-INVINCIBLE, AND\rSARASIM OF TESHWAVE, THE\rHIGH PRIESTESS OF SUNE,\rATTACKED THE DENIZENS OF\rTHE VALHINGEN GRAVEYARD" },
            { ((short)61, (short)1), "WITH A HOLY VENGEANCE. THEY\rCAME IN SEARCH OF TAIMALG\rAND HIS MERCENARY BAND, WHO\rASSAULTED THE GRAVEYARD AND\rDID NOT RETURN.\r\r\"SARASIM USED HER HOLY\rPOWER TO DISSIPATE AND TURN\rTHE UNDEAD THAT CONFRONTED" },
            { ((short)61, (short)2), "THEM. ARAMALG WIELDED HIS\rVORPAL SWORD AND SLEW THE\rFEW THAT FOUGHT HER POWER.\r\r\"TOGETHER, ARAMALG AND\rSARASIM PENETRATED THE\rGRAVEYARD TO AN EVIL MARBLE\rCRYPT. THEY FOUND AND\rSPLINTERED AN EMPTY COFFIN," },
            { ((short)61, (short)3), "BLESSING THE REMAINS AND\rSPRINKLING IT WITH HOLY\rWATER. THEN THEY CONFRONTED\rTHE OWNER OF THE COFFIN, A\rCREATURE OF GREAT EVIL AND\rTHE LEADER OF THE UNDEAD IN\rVALHINGEN, AN ANCIENT\rVAMPIRE. THE THREE BEGAN A\rFURIOUS MELEE." },
            { ((short)61, (short)4), "\r\"THE VAMPIRE WAS SWAYED BY\rARAMALG AND SARASIM'S\rPOWER, BUT WOULD NOT BE\rTURNED. THE VAMPIRE\rSHOUTED, \"I HAVE DEFEATED\rTAIMALG AND HIS WARRIORS, I\rWILL DEFEAT THE BROTHER OF\rTAIMALG AS WELL!\"" },
            { ((short)61, (short)5), "\r\"THE VAMPIRE SUMMONED AN\rARMY OF RATS AND TRIED TO\rCHARM SARASIM TO HIS SIDE,\rBUT TO NO AVAIL. SARASIM\rRESISTED HIS CHARM AND\rARAMALG CHARGED THROUGH THE\rMASSED VERMIN. THE VAMPIRE\rFELL BEFORE THE MIGHTY" },
            { ((short)61, (short)6), "BLOWS OF ARAMALG'S HOLY\rSWORD AND SARASIM'S\rENCHANTED MACE.\r\r\"DEFEATED, THE ANCIENT\rVAMPIRE DISSOLVED INTO GAS\rAND FLED TO HIS COFFIN.\rFINDING THE COFFIN\rDESTROYED HE RETURNED TO" },
            { ((short)61, (short)7), "SOLID FORM AND SCREAMED.\rSEIZING THE MOMENT ARAMALG\rGRABBED THE VAMPIRE AND\rHELD HIM WITH ALL OF HIS\rSTRENGTH. SARASIM RAN UP\rAND DROVE AN OAKEN STAKE\rTHROUGH THE VAMPIRE'S\rHEART.\r" },
            { ((short)61, (short)8), "\"ARAMALG AND SARASIM\rPERFORMED THE PROPER\rRITUALS TO BANISH THE\rVAMPIRE FOREVER. THEN,\rWOUNDED, ARAMALG AND\rSARASIM LEFT VALHINGEN\rGRAVEYARD. IT WAS BEYOND\rTHEIR POWER TO COMPLETELY\rCLEANSE THE EVIL PLACE, BUT" },
            { ((short)61, (short)9), "THEY HAD EXTRACTED PROPER\rVENGEANCE FOR THE DEATH OF\rTIAMALG AND HIS TROOPS.\"" },
            { ((short)62, (short)0), "A CLEANLY WRITTEN NOTE ON\rSTANDARD PAPER FOUND ON THE\rBODY OF A DEAD TRADER.\r\rALERAM,\r\r\"HELLO MY GOOD FRIEND. I\rHOPE YOU AND YOUR BROOD ARE\rWELL. I AM TIRED; TIRED OF" },
            { ((short)62, (short)1), "TREKKING THROUGH\rUNSPEAKABLE SWAMPS AND OVER\rUNCLIMBABLE MOUNTAINS TO\rTAKE MY MEAGER WARES TO\rUNGRATEFUL CUSTOMERS.\r\r\"ONLY ONE EVENT HAS SAVED\rTHIS YEAR'S SALES. I FOUND\rA CASTLE FULL OF HAPPY FOLK" },
            { ((short)62, (short)2), "WHO WERE VERY GOOD\rCUSTOMERS. THEY WERE\rSTARVED FOR GOODS AND NEWS\rFROM THE OUTSIDE WORLD. AND\rWELL THEY SHOULD BE, THEIR\rCASTLE WAS IN THE MIDDLE OF\rA SMALL FOREST, AND THE\rFOREST WAS IN THE MIDDLE OF\rA SWAMP!" },
            { ((short)62, (short)3), "\r\"THESE PEOPLE SEEMED TO\rKNOW NOTHING OF RECENT\rEVENTS. THEY STILL SPOKE OF\rPHLAN AS IF IT WERE IN ITS\rFULL FLOWER. AND THEY PAID\rIN OLD PHLANIAN GOLD\rSOVEREIGNS, DOUBLE THE\rWEIGHT OF THE NEWER GOLD" },
            { ((short)62, (short)4), "COINS!\r\r\"THOUGH THEY WERE OUT OF\rDATE, THEY WERE VERY\rFRIENDLY AND PROSPEROUS. I\rSAW MORE THAN ONE GEM\rGLITTER IN THE SUN, AND\rSEVERAL SWORDS SHOWED A\rFLASH THAT MADE ME THINK" },
            { ((short)62, (short)5), "THEY WERE MAGIC. IF YOU ARE\rWILLING TO DODGE THE VERMIN\rOF THE SWAMP I WOULD ADD\rTHIS CASTLE TO YOUR TRADING\rROUTE. SPEED TO YOUR HORSE,\rSTRENGTH TO YOUR ARM, AND\rSKILL TO YOUR TRADING.\"\r\rYOUR FRIEND," },
            { ((short)62, (short)6), "BURACH" },
            { ((short)63, (short)0), "TOLD IN PERFECT, STYLIZED,\rCOMMON.\r\r\"GENERATIONS AGO, FLESH\rTHINGS WERE FEWER AND WE\rHARD-SHELLED BEINGS RULED\rTHE SHORES OF LAZARA, WHAT\rFLESH THINGS CALL THE\rMOONSEA. WE GATHERED MUCH" },
            { ((short)63, (short)1), "GOLD AND PLATINUM, PLUS\rMANY GEMS FOR DECORATION\rAND TO APPEASE OUR OWN\rGODS. WE ARE QUITE ADEPT AT\rFINDING SUCH TRINKETS AS WE\rMAKE OUR HOME BY BURROWING\rWITH OUR MANDIBLES. WE KNOW\rTHE EARTH LIKE NONE OTHER\rCAN." },
            { ((short)63, (short)2), "\r\"WHEN FLESH THINGS BEGAN TO\rMULTIPLY, WE DID NOT LOOK\rON THEM AS INTELLIGENT.\rTHEY COULD NOT DECIPHER OUR\rGLORIOUS LANGUAGE OF SOUNDS\rAND MOVEMENT AND WE COULD\rNOT FATHOM INTELLIGENT\rCOMMUNICATION LIMITED TO" },
            { ((short)63, (short)3), "THEIR FEEBLE SQUEAKS AND\rGRUNTS.\r\r\"AS WE ASSUMED THE FLESH\rCREATURES WERE\rUNINTELLIGENT WE LOOKED ON\rTHEM AS SLOW, SOFT, WEAK,\rBUT TASTY, PREY. BUT THE\rPREY SOON CAME RIDING SWIFT" },
            { ((short)63, (short)4), "BEASTS, AND SO WERE NO\rLONGER SLOW. THEN THEY CAME\rIN METAL SHELLS, AND SO\rWERE NO LONGER SOFT. AND\rTHEN THEY CAME HURLING\rBALLS OF FIRE AND CLOUDS OF\rSTINK, AND SO WERE NO\rLONGER WEAK. OUR GODS TOLD\rUS THAT THE FLESH CREATURES" },
            { ((short)63, (short)5), "WOULD MULTIPLY AND THAT OUR\rONLY HOPE WAS TO RETREAT.\r\r\"WE RETREATED UNDERGROUND,\rINTO CAVERNS CARVED BY OUR\rOWN MANDIBLES. WE ONLY\rVENTURE TO THE SURFACE TO\rGUARD OUR LANDS AND TO FIND\rFOOD LESS POWERFUL THAN" },
            { ((short)63, (short)6), "YOURSELVES. WE HAVE KEPT\rTHE LOCATION OF OUR NEST\rSECRET FOR MANY\rGENERATIONS.\r\r\"BUT NOW YOU HAVE COME. YOU\rHAVE DEFEATED OUR WARRIORS,\rEVADED OUR TRAPS. WE ADMIT\rYOUR POWER. WE HAVE NOTHING" },
            { ((short)63, (short)7), "FURTHER TO GAIN BY COMBAT.\rIF YOU WILL LEAVE US IN\rPEACE YOU MAY TAKE THE GOLD\rAND GEMS THAT WERE SACRED\rTO OUR GODS, WE HAVE BEEN\rABANDONED BY THEM. IF YOU\rWILL NOT LEAVE US IN PEACE\rTHEN WE MUST FIGHT TO THE\rLAST. WHAT IS YOUR" },
            { ((short)63, (short)8), "DECISION?\"" },
            { ((short)64, (short)0), "TOLD AS JAUNTY, AFTER\rDINNER CONVERSATION.\r\r\"THIS IS AN OLD STORY THAT\rI FIRST HEARD WHILE SERVING\rAT THE CITADEL OF THE\rRAVEN. DIRG WAS THE USUAL\rBARBARIAN HERO -- THE TYPE\rABLE TO SNAP FIVE MEN'S" },
            { ((short)64, (short)1), "BACKS WITH HIS BARE HANDS,\rWRESTLE AND TAME THE CLOUD\rHORSES, PIERCE A MAN WITH A\rJAVELIN FROM MANY MILES\rAWAY, AND OTHER EQUALLY\rPREPOSTEROUS THINGS.\r\rTHE STORY GOES THAT DIRG\rAND HIS BAND OF MEN FOUND A" },
            { ((short)64, (short)2), "POOL OF UNFROZEN WATER\rWHILE WANDERING IN THE\rSNOWY WASTES. DIRG'S LITTLE\rPET LIZARD JEZMA GOT TOO\rCLOSE TO THE POOL AND\rDISCOVERED THAT NOT ONLY\rWAS THE WATER NOT FROZEN,\rIT WAS BOILING HOT; SO HOT\rTHAT IT COOKED THE SKIN" },
            { ((short)64, (short)3), "RIGHT OFF OF JEZMA.\r\r\"DIRG WAS SO ANGERED HE\rTHRUST HIS SPEAR INTO THE\rPOOL AND ROILED THE WATERS.\rTHE DEMON OF FIRE THAT\rINHABITED THE POOL WAS\rDISTURBED AND ROARED OUT OF\rTHE POOL TO DO BATTLE. THE" },
            { ((short)64, (short)4), "DEMON LEAPT FROM MAN TO\rMAN, CONSUMING THEM IN A\rSINGLE TOUCH.\r\r\"BUT THE DEMON OF FIRE\rCOULD NOT DEFEAT DIRG.\rNEITHER COULD DIRG FIND A\rWEAPON STRONG ENOUGH TO\rWITHSTAND THE CREATURE'S" },
            { ((short)64, (short)5), "FIRE. AFTER BATTLING FOR AN\rENTIRE DAY, DIRG FINALLY\rCALLED UPON HIS TOTEM GOD\rFOR AID. WITH THIS MAGICAL\rAID, DIRG WAS ABLE TO TRAP\rTHE FLAMING DEMON IN A\rTRIANGLE OF POWER WHERE\rSUPPOSEDLY HE IS EVEN TO\rTHIS DAY.\"" },
            { ((short)65, (short)0), "A SMALL WRINKLED PARCHMENT\rWITH ROUGHLY SCRATCHED\rNOTES.\r\r\"HOBGOBLINS TRANSFERRED OUT\rOF VALJEVO CASTLE. NOW\rREPLACED BY GIANTS AND\rTROLLS. SOUNDS VERY TOUGH.\r" },
            { ((short)65, (short)1), "\"STOJANOW GATE GUARDED BY\rBUGBEARS AND ETTINS. HEARD\rETTINS DIDN'T LIKE LIGHT.\rMUST BE CHARMED OR\rCONTROLLED. SOUNDS TOUGH!\r\r\"SOME SMUGGLERS SNEAK\rSUPPLIES THROUGH STOJANOW\rGATE TO THE BOSS. MUST" },
            { ((short)65, (short)2), "CHECK IT OUT.\r\r\"OVERHEARD HOBGOBLINS SAY A\rDRAGON SCARED THEM INTO\rLEAVING A NICE LAIR IN THE\rMOUNTAINS OUT EAST.\rCOULDN'T HAPPEN TO A NICER\rBUNCH OF CREEPS.\"" },
            { ((short)66, (short)0), "SEVERAL PIECES OF PAPER\rWITH HIGHLY ORGANIZED\rWRITING.\r\rSTRONG RUMOR: THE BOSS IS A\rDRAGON OR IS A HUMAN WHO\rCAN TAKE THE FORM OF A\rDRAGON.\r" },
            { ((short)66, (short)1), "VAGUE RUMOR: THE BOSS IS A\rMETALLIC DRAGON. NOT\rCONSIDERED LIKELY AS\rMETALLIC DRAGONS ARE\r\"GOOD\".\r\rFACT: THE BOSS HOLDS\rAUDIENCES IN VALJEVO\rCASTLE. CASTLE IS GUARDED" },
            { ((short)66, (short)2), "BY GROUPS OF BIG STUPID\rMONSTERS, WITH OCCASIONAL\rSMART HUMAN LEADERS.\r\rRUMOR: THE BOSS DOESN'T\rSPEND FULL TIME AT VALJEVO\rCASTLE.\r\rFACT: MAZE INSIDE CASTLE" },
            { ((short)66, (short)3), "WALL; PASSWORDS ARE NEEDED\rTO GET PAST CASTLE GATES.\r\rRUMOR: THE BOSS HAS BEEN\rSENDING OUT MESSENGERS TO\rTHE TRIBES OF MONSTERS IN\rTHE AREA TO RECRUIT NEW\rUNITS.\r" },
            { ((short)66, (short)4), "VAGUE RUMOR: THE BOSS IS\rRECRUITING NEW UNITS IN\rPREPARATION FOR AN ASSAULT\rTO RETAKE THE CIVILIZED\rSECTIONS OF PHLAN." },
            { ((short)67, (short)0), "A LETTER ON CLEAN WHITE\rPAPER IN A STRONG HAND\r\rTO:\rTHE BOSS\rVALJEVO CASTLE, PHLAN\r\rSIR,\r" },
            { ((short)67, (short)1), "\"I CATEGORICALLY REJECT\rYOUR DEMAND THAT I SUBMIT\rMY ISLAND AND MY POWERS TO\rYOUR CONTROL. I AM A FREE\rMAN AND I WILL REMAIN FREE.\rNO PETTY TYRANT CAN ORDER\rABOUT A TRUE MAGE.\r\r\"IF YOU OR YOUR TROOPS MAKE" },
            { ((short)67, (short)2), "ANY MOVE TOWARD SORCERER'S\rISLAND I SHALL SEND AN ARMY\rOF MY UNSTOPPABLE AQUATIC\rCREATIONS DOWN THE BARREN\rRIVER AND SINK YOUR\rPRECIOUS CASTLE. UNTIL NOW\rYOU HAVE BEEN BENEATH MY\rNOTICE. IF YOU VALUE YOUR\rEMPIRE, LET US KEEP IT THAT" },
            { ((short)67, (short)3), "WAY.\"\r\rSIGNED\rYARASH, THE SORCERER" },
        };

        public static short LineCount(short index)
        {
            short result;
            return LineCounts.TryGetValue(index, out result) ? result : (short)0;
        }

        public static string TextChunk(short index, short chunk)
        {
            string result;
            return Chunks.TryGetValue((index, chunk), out result) ? result : string.Empty;
        }
    }
}